package com.example.domain.model.i18n

internal object DuaPt2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Proteção contra todo mal", "Em nome de Allah, com cujo nome nada na terra ou no céu pode causar dano, e Ele é o Ouvinte, o Sapiente.", "Recitado três vezes de manhã e três vezes à noite.", "Quem o recitar três vezes de manhã e à noite, nada lhe causará dano."),
        "dua_raditu_billahi" to DuaText("Satisfeito com Allah como Senhor", "Estou satisfeito com Allah como Senhor, com o Islã como religião e com Muhammad ﷺ como profeta.", "Recitado três vezes de manhã e à noite.", "Allah se compromete a satisfazer tal servo no Dia do Juízo."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah me basta)", "Allah me basta; não há divindade senão Ele; nEle deposito minha confiança, e Ele é o Senhor do Trono Grandioso.", "Recitado sete vezes de manhã e à noite.", "Um versículo do Alcorão; Allah basta diante das aflições deste mundo e do outro."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Subhanallahi wa bihamdihi", "Glorificado seja Allah, e a Ele pertence todo louvor.", "Recitado cem vezes ao dia.", "Quem o recitar cem vezes ao dia, seus pecados são perdoados, mesmo que sejam como a espuma do mar."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Não há divindade senão Allah, único, sem parceiro. D'Ele é o domínio, a Ele pertence o louvor, e Ele é capaz de todas as coisas.", "Grande mérito ao ser recitado cem vezes ao dia.", "Equivale a libertar dez escravos, cem boas ações, o perdão de cem pecados e proteção do demônio até o anoitecer."),
        "dua_leaving_mosque" to DuaText("Ao sair da mesquita", "Ó Allah, peço-Te de Tua graça.", "Recitado ao sair da mesquita com o pé esquerdo.", "Pedido da graça e do sustento de Allah ao sair da mesquita."),
        "dua_after_adhan" to DuaText("Depois do chamado à oração", "Ó Allah, Senhor deste chamado perfeito e da oração que se aproxima, concede a Muhammad ﷺ a intercessão e a excelência, e eleva-o à posição louvável que lhe prometeste.", "Recitado logo após o término do chamado à oração.", "Quem o recitar terá garantida a intercessão do Profeta ﷺ no Dia da Ressurreição."),
        "dua_after_salah_istighfar" to DuaText("Depois da oração obrigatória", "Peço perdão a Allah (3 vezes). Ó Allah, Tu és a Paz, e de Ti vem a paz; bendito sejas, ó Detentor da Majestade e da Generosidade.", "Recitado logo após a saudação final.", "O Profeta ﷺ recitava isso após cada oração obrigatória."),
        "dua_after_salah_help_dhikr" to DuaText("Ajuda-me a lembrar de Ti", "Ó Allah, ajuda-me a lembrar de Ti, a agradecer-Te e a adorar-Te da melhor forma.", "Depois de cada oração — o Profeta ﷺ recomendou isso a Muadh (que Allah esteja satisfeito com ele).", "Recomendação especial do Profeta ﷺ para excelência e constância na adoração."),
        "dua_sleep_tasbeeh" to DuaText("Tasbih de Fátima antes de dormir", "Subhanallah (33 vezes), Alhamdulillah (33 vezes), Allahu akbar (34 vezes).", "Recitado antes de dormir — o Profeta ﷺ ensinou a Fátima e Ali (que Allah esteja satisfeito com eles).", "O Profeta ﷺ disse que isso é melhor que um servo."),
        "dua_sleep_qina_adhab" to DuaText("Proteção contra o castigo", "Ó Allah, protege-me do Teu castigo no dia em que ressuscitares os Teus servos.", "Recitado três vezes com a mão direita sob a face.", "Torna o sono uma lembrança da morte e preparação para o Além."),
        "dua_bad_dream" to DuaText("Ao ter um pesadelo", "Busco refúgio em Allah contra o demônio amaldiçoado.", "Ao ter um pesadelo: soprar levemente três vezes para o lado esquerdo e mudar de posição.", "O pesadelo não causará dano; não deve ser contado a ninguém."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ó Vivente, ó Subsistente", "Ó Vivente, ó Subsistente, por Tua misericórdia busco socorro.", "Quando um assunto se torna muito difícil.", "O Profeta ﷺ recitava isso quando algo o afligia."),
        "dua_entering_market" to DuaText("Ao entrar no mercado", "Não há divindade senão Allah, único, sem parceiro. D'Ele é o domínio e a Ele pertence o louvor. Ele dá vida e dá morte, e Ele é vivo e não morre. Em Sua mão está todo o bem, e Ele é capaz de todas as coisas.", "Recitado ao entrar no mercado.", "A tradição narra uma recompensa imensa para quem o recita."),
        "dua_adam_forgiveness" to DuaText("A súplica de Adão", "Nosso Senhor, injustiçamos a nós mesmos, e se não nos perdoares e não tiveres misericórdia de nós, certamente estaremos entre os perdedores.", "A súplica de arrependimento de Adão e Eva (que a paz esteja com eles).", "O primeiro arrependimento da humanidade — aceito por Allah."),
        "dua_abu_bakr" to DuaText("Súplica ensinada a Abu Bakr", "Ó Allah, cometi grande injustiça contra mim mesmo, e ninguém perdoa os pecados senão Tu; perdoa-me, pois, com um perdão vindo de Ti, e tem misericórdia de mim, pois Tu és o Perdoador, o Misericordioso.", "O Profeta ﷺ ensinou a Abu Bakr (que Allah esteja satisfeito com ele) para recitar na oração (após o tashahhud).", "Súplica recomendada ao final da oração."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar diário", "Peço perdão a Allah e a Ele me volto arrependido.", "O Profeta ﷺ pedia perdão mais de setenta vezes ao dia.", "O Profeta ﷺ disse: Peço perdão a Allah e me arrependo mais de setenta vezes ao dia."),
        "dua_laylatul_qadr" to DuaText("Súplica para a Noite do Decreto", "Ó Allah, Tu és Perdoador e amas perdoar; perdoa-me, então.", "Ensinada a Aisha (que Allah esteja satisfeita com ela) para a Noite do Decreto.", "Súplica especial para as últimas noites do Ramadã e a Noite do Decreto."),
        "dua_family_coolness" to DuaText("O frescor dos olhos (família)", "Nosso Senhor, concede-nos em nossas esposas e descendência o frescor dos olhos, e faze de nós um exemplo para os piedosos.", "Súplica alcorânica por uma família virtuosa.", "Pela paz no lar e por descendência virtuosa."),
        "dua_righteous_children" to DuaText("Por descendência virtuosa", "Meu Senhor, concede-me de Tua parte uma descendência virtuosa; certamente, Tu és o Ouvinte da súplica.", "A súplica do profeta Zacarias (que a paz esteja com ele).", "Súplica alcorânica pedindo filhos."),
        "dua_ibrahim_prayer_family" to DuaText("Os que cumprem a oração", "Meu Senhor, faze de mim e de minha descendência cumpridores da oração. Nosso Senhor, aceita minha súplica. Nosso Senhor, perdoa-me, a meus pais e aos crentes no Dia da Prestação de Contas.", "A súplica de Abraão (que a paz esteja com ele) por si e sua descendência.", "Recitada comumente ao final da oração."),
        "dua_newlywed" to DuaText("Felicitação aos recém-casados", "Que Allah te abençoe, derrame bênçãos sobre ti e vos una no bem.", "Dita a quem se casou.", "Felicitação recomendada para o casamento."),
        "dua_before_eating" to DuaText("Antes de comer", "Em nome de Allah. (Se esquecer:) Em nome de Allah, no início e no fim.", "Antes de comer; se esquecer, diz-se no meio.", "Ao dizer Bismillah, o demônio não participa da refeição."),
        "dua_after_eating" to DuaText("Depois de comer", "Louvado seja Allah, que me alimentou e me deu este sustento sem qualquer força ou poder meu.", "Recitado ao terminar de comer.", "Quem o recita tem seus pecados passados perdoados."),
        "dua_host" to DuaText("Pelo anfitrião", "Ó Allah, abençoa o que lhes deste de sustento, perdoa-os e tem misericórdia deles.", "Pelo anfitrião, depois de comer na casa de alguém.", "Agradecimento recomendado ao anfitrião."),
        "dua_breaking_fast" to DuaText("Ao quebrar o jejum", "A sede se foi, as veias se umedeceram e a recompensa está garantida, se Allah quiser.", "Recitado ao quebrar o jejum (iftar).", "O Profeta ﷺ dizia isso ao quebrar o jejum."),
        "dua_new_clothes" to DuaText("Ao vestir roupa nova", "Ó Allah, a Ti pertence o louvor; Tu me vestiste com isto. Peço-Te o bem dele e o bem para o qual foi feito, e busco refúgio em Ti do mal dele e do mal para o qual foi feito.", "Ao vestir roupa nova, mencionando seu nome (camisa, turbante, etc.).", "O Profeta ﷺ recitava isso ao vestir roupa nova."),
        "dua_rabbana_atina" to DuaText("O bem nesta vida e na outra", "Nosso Senhor, concede-nos o bem nesta vida e o bem na outra vida, e protege-nos do castigo do Fogo.", "A súplica mais recitada pelo Profeta ﷺ.", "Uma súplica que reúne todo o bem desta vida e da próxima."),
        "dua_rabbi_zidni_ilma" to DuaText("Aumento do conhecimento", "Meu Senhor, aumenta o meu conhecimento.", "Para o aumento do conhecimento.", "Allah ordenou ao Profeta ﷺ pedir apenas o aumento do conhecimento."),
        "dua_musa_sharh_sadr" to DuaText("Abertura do peito (Moisés)", "Meu Senhor, expande meu peito, facilita minha tarefa e desata o nó da minha língua, para que entendam minha fala.", "Antes de um exame, discurso ou tarefa difícil.", "A súplica de Moisés (que a paz esteja com ele) — para tranquilidade e facilidade."),
        "dua_la_tuzigh" to DuaText("Firmeza do coração", "Nosso Senhor, não desvies nossos corações depois de nos teres guiado, e concede-nos misericórdia de Tua parte; certamente, Tu és o Doador Generoso.", "Pela firmeza na orientação.", "Súplica pela firmeza na fé."),
        "dua_ya_muqallib" to DuaText("Ó Transformador dos corações", "Ó Transformador dos corações, firma meu coração em Tua religião.", "O Profeta ﷺ recitava frequentemente esta súplica.", "Segundo Umm Salama (que Allah esteja satisfeita com ela), a súplica mais recitada pelo Profeta ﷺ."),
        "dua_la_tuakhidhna" to DuaText("Os últimos versículos de Al-Baqarah", "Nosso Senhor, não nos condenes se esquecermos ou cometermos erro. Nosso Senhor, não nos imponhas um fardo como impuseste aos que vieram antes de nós. Nosso Senhor, não nos sobrecarregues além do que podemos suportar. Perdoa-nos, absolve-nos e tem misericórdia de nós. Tu és nosso Protetor; ajuda-nos contra o povo incrédulo.", "Recitado à noite antes de dormir — os dois últimos versículos de Al-Baqarah.", "Quem os recita à noite, eles lhe bastam."),
        "dua_visiting_sick" to DuaText("Visita ao doente", "Peço a Allah, o Grandioso, Senhor do Trono Grandioso, que te cure.", "Recitado sete vezes ao visitar o doente.", "Se ainda não chegou a hora da morte, Allah o cura."),
        "dua_ruqyah_pain" to DuaText("Contra dor no corpo", "Busco refúgio em Allah e em Seu poder contra o mal que sinto e temo.", "Colocar a mão sobre a dor, dizer Bismillah três vezes, depois esta súplica sete vezes.", "O Profeta ﷺ ensinou isso a Uthman ibn Abi al-As (que Allah esteja satisfeito com ele) contra a dor."),
        "dua_ruqyah_nabawi" to DuaText("Súplica de cura profética para o doente", "Ó Allah, Senhor dos homens, remove o sofrimento, cura, Tu és o Curador, não há cura senão a Tua cura, uma cura que não deixa doença alguma.", "Recitado enquanto se passa a mão sobre o doente.", "O Profeta ﷺ recitava isso ao visitar seus familiares doentes."),
        "dua_kalimat_tammat" to DuaText("Refúgio nas palavras perfeitas", "Busco refúgio nas palavras perfeitas de Allah contra o mal do que Ele criou.", "Ao pousar em um lugar ou ao anoitecer.", "Quem recita isso ao pousar em um lugar, nada lhe causará dano até que parta dali."),
        "dua_evil_eye" to DuaText("Proteção das crianças (mau-olhado)", "Confio-vos às palavras perfeitas de Allah, contra todo demônio e criatura venenosa, e contra todo olhar mau.", "O Profeta ﷺ recitava isso sobre Hassan e Hussein (que Allah esteja satisfeito com eles).", "Súplica de proteção para crianças contra o mau-olhado e o mal."),
        "dua_seeing_afflicted" to DuaText("Ao ver alguém aflito", "Louvado seja Allah, que me protegeu daquilo com que te afligiu, e me favoreceu sobre muitas de Suas criaturas.", "Ao ver alguém em aflição (recitar silenciosamente).", "Quem o recita permanece protegido daquela aflição."),
        "dua_istikhara" to DuaText("A súplica de Istikhara", "Ó Allah, busco o bem através do Teu conhecimento, peço poder através do Teu poder e peço de Tua imensa graça. Tu és capaz, eu não sou; Tu sabes, eu não sei; e Tu és o Conhecedor do oculto. Ó Allah, se sabes que este assunto é bom para mim, em minha religião, minha vida e meu destino, então decreta-o para mim, facilita-o para mim e abençoa-o para mim. E se sabes que este assunto é mau para mim, então afasta-o de mim e a mim dele, e decreta-me o bem onde quer que esteja, e depois faze-me satisfeito com isso.", "Depois de duas unidades de oração voluntária, para buscar o bem em um assunto permitido.", "O Profeta ﷺ ensinava a Istikhara aos companheiros como uma sura do Alcorão."),
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma bika asbahna", "Ó Allah, por Ti amanhecemos e por Ti anoitecemos; por Ti vivemos e morremos, e a Ti é a ressurreição.", "Recitado pela manhã.", "O Profeta ﷺ ensinava isso aos companheiros de manhã e à noite."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma bika amsayna", "Ó Allah, por Ti anoitecemos e por Ti amanhecemos; por Ti vivemos e morremos, e a Ti é o retorno.", "Recitado à noite.", "O Profeta ﷺ ensinava isso aos companheiros de manhã e à noite."),
        "dua_afiyah_morning" to DuaText("Súplica pelo bem-estar", "Ó Allah, peço-Te perdão e bem-estar nesta vida e na outra.", "O Profeta ﷺ nunca deixava esta súplica de manhã e à noite.", "Nada melhor que o bem-estar foi dado a alguém."),
        "dua_afini_fi_badani" to DuaText("Bem-estar do corpo, audição e visão", "Ó Allah, dá bem-estar ao meu corpo, dá bem-estar à minha audição, dá bem-estar à minha visão. Não há divindade senão Tu.", "Recitado três vezes de manhã e três vezes à noite.", "Súplica pela saúde e proteção dos sentidos."),
        "dua_ya_hayyu_aslih" to DuaText("Endireita todos os meus assuntos", "Ó Vivente, ó Subsistente, por Tua misericórdia busco socorro. Endireita todos os meus assuntos e não me entregues a mim mesmo nem por um piscar de olhos.", "O Profeta ﷺ recomendou a Fátima (que Allah esteja satisfeita com ela) recitar de manhã e à noite.", "Pedido de auxílio de Allah em todos os assuntos."),
        "dua_subhanallah_adada_khalqihi" to DuaText("O tasbih de Juwayriya", "Glorificado seja Allah e louvado seja Ele — tantas vezes quanto Suas criaturas, conforme Seu agrado, tão pesado quanto Seu Trono e tão extenso quanto a tinta de Suas palavras.", "Recitado três vezes pela manhã — mais pesado que horas de lembrança.", "Estas quatro palavras, ditas três vezes, pesam mais que a lembrança feita da manhã ao meio-dia."),
        "dua_salawat" to DuaText("A saudação abraâmica", "Ó Allah, abençoa Muhammad ﷺ e a família de Muhammad, como abençoaste Abraão e a família de Abraão; certamente, Tu és Louvável, Glorioso. Ó Allah, envia bênçãos sobre Muhammad ﷺ e a família de Muhammad, como enviaste bênçãos sobre Abraão e a família de Abraão; certamente, Tu és Louvável, Glorioso.", "Na oração e a qualquer momento como saudação ao Profeta ﷺ.", "Quem envia uma saudação, Allah lhe envia dez bênçãos (Muslim 408)."),
        "dua_wudu_after" to DuaText("Depois da ablução", "Testemunho que não há divindade senão Allah, único, sem parceiro, e que Muhammad ﷺ é Seu servo e mensageiro. Ó Allah, faze-me dos que se arrependem e dos que se purificam.", "Ao concluir a ablução.", "Todos os oito portões do Paraíso se abrem, e pode entrar por qualquer um deles."),
        "dua_wudu_before" to DuaText("Antes da ablução", "Em nome de Allah.", "Ao iniciar a ablução.", "A ablução de quem não menciona o nome de Allah não é completa."),
        "dua_istiftah" to DuaText("A súplica de abertura da oração", "Ó Allah, glorificado sejas, e louvado sejas; bendito é o Teu nome, exaltada é a Tua majestade, e não há divindade senão Tu.", "No início da oração, logo após o takbir de abertura.", "Súplica de abertura recomendada da oração."),
        "dua_ruku" to DuaText("Na inclinação (ruku)", "Glorificado seja meu Senhor, o Grandioso.", "Pelo menos três vezes na inclinação.", "Glorificação recomendada durante a inclinação."),
        "dua_sujood" to DuaText("Na prostração", "Glorificado seja meu Senhor, o Altíssimo.", "Pelo menos três vezes na prostração.", "O servo está mais próximo de seu Senhor durante a prostração (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Ao erguer-se da inclinação", "Allah ouve quem O louva. Nosso Senhor, a Ti pertence todo louvor.", "Ao erguer-se da inclinação e ficar ereto.", "Cujo louvor coincidir com o dos anjos, terá seus pecados passados perdoados."),
        "dua_between_sajdas" to DuaText("Entre as duas prostrações", "Meu Senhor, perdoa-me; meu Senhor, perdoa-me.", "Sentado entre as duas prostrações.", "Súplica recomendada nesta posição sentada."),
        "dua_before_salam_four" to DuaText("Proteção contra quatro coisas (antes da saudação final)", "Ó Allah, busco refúgio em Ti do castigo do Inferno, do castigo da sepultura, das provações da vida e da morte, e do mal da provação do Anticristo (Dajjal).", "Depois do último tashahhud e da saudação ao Profeta, antes da saudação final.", "O Profeta ﷺ ordenou buscar refúgio contra estas quatro coisas."),
        "dua_qunoot_witr" to DuaText("Qunut na oração Witr", "Ó Allah, guia-me entre os que guiaste, dá-me bem-estar entre os que deste bem-estar, toma-me sob Tua proteção entre os que protegeste, abençoa-me no que me deste, e protege-me do mal que decretaste. Certamente, Tu decretas e não é decretado contra Ti, e quem Tu proteges não é humilhado. Nosso Senhor, bendito e exaltado és Tu.", "Na oração Witr — o Profeta ﷺ ensinou a Hassan ibn Ali (que Allah esteja satisfeito com ele).", "Qunut recomendado da oração Witr."),
        "dua_qunoot_hanafi" to DuaText("Qunut (Allahumma inna nastainuka)", "Ó Allah, pedimos-Te ajuda e perdão, cremos em Ti e confiamos em Ti, louvamos-Te da melhor forma, agradecemos-Te e não somos ingratos, e abandonamos quem Te desobedece. Ó Allah, só a Ti adoramos, por Ti rezamos e nos prostramos, a Ti nos apressamos e nos esforçamos, esperamos Tua misericórdia e tememos Teu castigo; certamente, Teu castigo alcançará os incrédulos.", "Na oração Witr — prática da escola Hanafi.", "Transmitido de Umar (que Allah esteja satisfeito com ele) no Qunut."),
        "dua_sleep_aslamtu" to DuaText("Últimas palavras antes de dormir", "Ó Allah, entrego minha alma a Ti, confio meu assunto a Ti, recosto minhas costas em Ti, por desejo e temor de Ti. Não há refúgio nem salvação de Ti senão em Ti mesmo. Creio em Teu Livro que enviaste e em Teu Profeta que mandaste.", "Após a ablução, deitado sobre o lado direito — como últimas palavras.", "Se morrer naquela noite, morrerá na fitra (o Islã)."),
        "dua_waking_night" to DuaText("Ao acordar durante a noite", "Não há divindade senão Allah, único, sem parceiro; d'Ele é o domínio e a Ele pertence o louvor, e Ele é capaz de todas as coisas. Louvado seja Allah, glorificado seja Allah, não há divindade senão Allah, Allah é o Maior, e não há poder nem força senão em Allah. Ó Allah, perdoa-me.", "Ao acordar durante a noite.", "A súplica é atendida, e se fizer a ablução e rezar, sua oração é aceita."),
        "dua_hamm_ibn_masud" to DuaText("Súplica contra a angústia (Ibn Masud)", "Ó Allah, sou Teu servo, filho de Teu servo, filho de Tua serva. Minha testa está em Tua mão, Teu julgamento sobre mim se cumpre, Tua decisão sobre mim é justa. Peço-Te por todo nome com que Te nomeaste, ou que revelaste em Teu Livro, ou que ensinaste a alguma de Tuas criaturas, ou que guardaste contigo no conhecimento do oculto — faze do Alcorão a primavera do meu coração, a luz do meu peito, a cura da minha angústia e o fim da minha aflição.", "Em momentos de angústia e aflição — Allah transforma a angústia em alegria.", "Allah remove a angústia e a aflição e concede alegria em seu lugar."),
        "dua_difficulty_sahl" to DuaText("Quando algo é difícil", "Ó Allah, nada é fácil senão o que Tu tornas fácil, e Tu tornas fácil a dificuldade quando queres.", "Quando algo parece difícil.", "Facilidade em provas e tarefas difíceis."),
        "dua_musibah" to DuaText("Diante de uma desgraça (Istirja)", "Certamente pertencemos a Allah, e a Ele retornamos. Ó Allah, recompensa-me por minha desgraça e concede-me algo melhor em troca.", "Diante de qualquer perda ou desgraça.", "Allah certamente concede algo melhor — assim aconteceu com Umm Salama (que Allah esteja satisfeita com ela)."),
        "dua_debt" to DuaText("Libertação das dívidas", "Ó Allah, basta-me o que é lícito em vez do que é proibido, e torna-me, por Tua graça, independente de todos além de Ti.", "Para o pagamento de dívidas — ensinada por Ali (que Allah esteja satisfeito com ele).", "Mesmo que a dívida fosse do tamanho de uma montanha, Allah faria com que fosse paga."),
        "dua_anger" to DuaText("Ao sentir raiva", "Busco refúgio em Allah contra o demônio amaldiçoado.", "Quando surge a raiva.", "O Profeta ﷺ disse: Se disser isso, sua raiva se dissipará."),
        "dua_waswasa" to DuaText("Contra dúvidas sobre a fé", "Creio em Allah e em Seus mensageiros.", "Quando surgem sussurros diabólicos sobre a fé.", "Ao surgir a dúvida, diga isso e pare (também busque refúgio em Allah)."),
        "dua_travel_full" to DuaText("A súplica completa de viagem", "Ó Allah, pedimos-Te nesta viagem retidão, piedade e ações que Te agradem. Ó Allah, facilita-nos esta viagem e encurta-nos a sua distância. Ó Allah, Tu és o companheiro na viagem e o protetor da família.", "Ao partir em viagem, após dizer 'Subhanalladhi sakhkhara'.", "Súplica completa recomendada de viagem."),
        "dua_return_travel" to DuaText("Retorno da viagem", "Retornamos, arrependidos, adoradores e louvando nosso Senhor.", "Ao retornar de uma viagem.", "O Profeta ﷺ dizia isso ao retornar de uma viagem."),
        "dua_farewell_traveller" to DuaText("Despedida do viajante", "Confio a Allah tua religião, tua honestidade e o fim de tuas ações.", "Ao se despedir de um viajante.", "O que é confiado a Allah não se perde."),
        "dua_entering_town" to DuaText("Ao pousar em um lugar", "Busco refúgio nas palavras perfeitas de Allah contra o mal de toda criação.", "Ao pousar em um lugar ou chegar a uma nova cidade.", "Nada lhe causará dano até que parta dali."),
        "dua_boarding_ship" to DuaText("Ao embarcar em um navio", "Em nome de Allah é sua partida e sua ancoragem; certamente meu Senhor é Perdoador, Misericordioso.", "Ao embarcar em um navio ou veículo — palavras de Noé (que a paz esteja com ele).", "Versículo alcorânico — a súplica de Noé para seu navio."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar com Hayyul Qayyum", "Peço perdão a Allah, além do qual não há divindade, o Vivente, o Subsistente, e a Ele me volto arrependido.", "Para o arrependimento.", "Os pecados são perdoados, mesmo que se tenha fugido do campo de batalha."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir warham", "Meu Senhor, perdoa e tem misericórdia, pois Tu és o Melhor dos misericordiosos.", "Súplica alcorânica por perdão e misericórdia.", "O último versículo de Al-Muminun."),
        "dua_majlis_kaffarah" to DuaText("Expiação da reunião", "Glorificado sejas, ó Allah, e louvado sejas. Testemunho que não há divindade senão Tu. Peço-Te perdão e a Ti me volto arrependido.", "Ao sair de uma reunião.", "Serve como expiação pelos erros cometidos na reunião."),
        "dua_jami_forgiveness" to DuaText("Súplica abrangente de perdão", "Ó Allah, perdoa meu erro, minha ignorância, meu excesso em meus assuntos, e o que Tu sabes melhor que eu.", "A súplica abrangente do Profeta ﷺ.", "O Profeta ﷺ costumava fazer esta súplica."),
        "dua_parents_nuh" to DuaText("Súplica de Noé pelos pais", "Meu Senhor, perdoa-me, a meus pais, a todo aquele que entrar em minha casa como crente, e a todos os crentes e crentes.", "Pelos pais e pelos crentes.", "A súplica do profeta Noé (que a paz esteja com ele)."),
        "dua_shukr_parents" to DuaText("Gratidão pelos pais e boa descendência", "Meu Senhor, inspira-me a agradecer por Tua graça que concedeste a mim e a meus pais, e a fazer boas ações que Te agradem, e torna também minha descendência virtuosa. Volto-me a Ti arrependido, e sou dos submissos.", "Súplica alcorânica para a idade de quarenta anos.", "Gratidão, boas ações e correção da descendência — tudo em uma súplica."),
        "dua_intimacy" to DuaText("Antes da união conjugal", "Em nome de Allah. Ó Allah, afasta de nós o demônio, e afasta o demônio do que nos concederes.", "Antes da união conjugal.", "Se um filho for concedido, o demônio jamais lhe causará dano."),
        "dua_ibrahim_children_protection" to DuaText("Proteção da terra natal e da descendência", "Meu Senhor, torna esta cidade segura, e afasta-me e a meus descendentes de adorar ídolos.", "A súplica de Abraão (que a paz esteja com ele) pela cidade e pela descendência.", "Súplica pela firmeza na fé pura."),
        "dua_drinking_milk" to DuaText("Ao beber leite", "Ó Allah, abençoa-nos nisto e concede-nos mais.", "Ao beber leite.", "Nada basta como alimento e bebida ao mesmo tempo, exceto o leite."),
        "dua_iftar_host" to DuaText("Ao quebrar o jejum como convidado", "Que os que jejuam quebrem o jejum em vossa casa, que os virtuosos comam de vossa comida, e que os anjos rezem por vós.", "Ao quebrar o jejum na casa de alguém como convidado.", "A súplica de gratidão do Profeta ﷺ pelo anfitrião."),
        "dua_seeing_first_fruit" to DuaText("Ao ver o primeiro fruto", "Ó Allah, abençoa-nos em nossos frutos, em nossa cidade, em nosso sa e em nosso mudd.", "Ao ver o primeiro fruto da estação.", "Súplica por bênção no sustento e na cidade."),
        "dua_good_news" to DuaText("Ao receber boas notícias", "Louvado seja Allah, por cuja graça as boas ações se completam.", "Ao receber uma notícia alegre (e prostração de gratidão).", "O Profeta ﷺ dizia isso ao ver algo agradável."),
        "dua_looking_mirror" to DuaText("Ao olhar no espelho", "Ó Allah, assim como embelezaste minha aparência, embeleza também meu caráter.", "Ao olhar no espelho.", "O Profeta ﷺ recitava esta súplica (também transmitida sem a menção do espelho)."),
        "dua_rabbana_taqabbal" to DuaText("Aceitação das boas ações", "Nosso Senhor, aceita de nós; certamente, Tu és o Ouvinte, o Sapiente. E aceita nosso arrependimento; certamente, Tu és o Aceitador do arrependimento, o Misericordioso.", "Dita por Abraão e Ismael (que a paz esteja com eles) durante a construção da Caaba.", "Súplica pela aceitação após cada boa ação."),
    )
}
